// Logo extraído del "Brand Tool Kit - EMT Medical Group" (v1.0, junio 2026).
// PNG con fondo transparente, generado a partir del PDF vectorial original.
// LOGO_PRINCIPAL_PNG: logotipo completo (EMT + isotipo + MEDICAL GROUP), 800x111.
// ISOTIPO_PNG: solo el símbolo (versión 1 tono, navy), 400x203.

export const LOGO_PRINCIPAL_PNG = 'data:image/png;base64,'

export const ISOTIPO_PNG = 'data:image/png;base64,'

export const BRAND_COLORS = {
  azulOceanoProfundo: [4, 56, 96] as [number, number, number], // #043860
  azulVenecia: [0, 87, 142] as [number, number, number], // #00578E
  amarilloVivo: [239, 253, 158] as [number, number, number], // #EFFD9E
}

/**
 * Dibuja el logo principal centrado (y opcionalmente los datos de contacto
 * debajo) en la parte superior de un PDF. Devuelve el eje Y donde puede
 * continuar el contenido siguiente.
 */
export function drawBrandHeader(doc: import('jspdf').default, opts?: { withContact?: boolean }): number {
  const pageWidth = doc.internal.pageSize.getWidth()
  const logoWidth = 70
  const logoHeight = logoWidth * (111 / 800)
  const x = (pageWidth - logoWidth) / 2
  doc.addImage(LOGO_PRINCIPAL_PNG, 'PNG', x, 10, logoWidth, logoHeight)
  let y = 10 + logoHeight + 6

  if (opts?.withContact !== false) {
    doc.setFont('helvetica', 'normal')
    doc.setFontSize(9)
    doc.setTextColor(60, 60, 60)
    doc.text('Calle 10 esquina José A. Patiño No. 2A, Urbanización Villa Olga,', pageWidth / 2, y, { align: 'center' })
    y += 5
    doc.text('Santiago de los Caballeros, República Dominicana.', pageWidth / 2, y, { align: 'center' })
    y += 5
    doc.text('Tel: (809) 330-1538   |   WhatsApp: (809) 570-8705', pageWidth / 2, y, { align: 'center' })
    y += 5
    doc.text('www.emtmedicalgroup.do   |   emtmedicalgroup@gmail.com', pageWidth / 2, y, { align: 'center' })
    y += 5
    doc.setTextColor(0, 0, 0)
  }

  return y
}
